import json
from pathlib import Path
wanted = {'NLNET-OPEN-CALL-DELIVERY-FIT', 'CATALOGUE-PAID-BUYER-REPLY-REHEARSAL'}
for page in sorted(Path('world/pages').glob('missions-*.json')):
    data = json.loads(page.read_text())
    rows = data if isinstance(data, list) else next((value for value in data.values() if isinstance(value, list) and any(isinstance(row, dict) and 'mission_id' in row for row in value)), [])
    for row in rows:
        if isinstance(row, dict) and row.get('mission_id') in wanted:
            print(json.dumps({key: row.get(key) for key in ('mission_id', 'status', 'agent_id', 'lease_expires_at', 'evidence')}))
for path in (Path('products/services/nlnet-csv-milestone'), Path('products/services/catalogue-inbound-cad')):
    print(json.dumps({'directory': str(path), 'committed_files': sorted(str(file) for file in path.rglob('*') if file.is_file())}))
